using System.Buffers.Binary;
using Orbit.Host;
using Orbit.Host.Platform;

/// <summary>Pure startup scheduling checks; only generated bytes, fake capture and fake encoding.</summary>
public static class StreamStartChecks
{
    public static async Task RunAsync(Action<bool, string> check)
    {
        var health = new GpuEncodeHealthWindow();
        for (var i = 0; i < GpuEncodeHealthWindow.WarmupEncodes; i++)
            health.Observe(i < 10 ? 120 : 15, false, i * 100_000L);
        check(health.Count == 0, "GPU health: the first thirty encoder calls cannot poison the steady-state verdict");
        for (var i = 0; i < 100; i++) health.Observe(900, true, 3_000_000 + i * 100_000L);
        check(health.Count == 0, "GPU health: expensive keyframes are excluded from steady-state measurements");
        double? median = null;
        for (var i = 0; i < 14; i++) median = health.Observe(15, false, 20_000_000 + i * 100_000L);
        check(median is null, "GPU health: a long window with fewer than fifteen eligible samples cannot decide fallback");
        median = health.Observe(15, false, 21_400_000);
        check(median is 15, "GPU health: slow startup followed by sustained fifteen-ms deltas measures the healthy median");
        health.Reset();
        for (var i = 0; i < GpuEncodeHealthWindow.WarmupEncodes; i++) health.Observe(66, false, i);
        for (var i = 0; i < 20; i++) median = health.Observe(66, false, i * 1000);
        check(median is null, "GPU health: fifteen or more samples must also span a full second");
        median = health.Observe(66, false, 1_000_000);
        check(median is 66, "GPU health: sustained sixty-six-ms encoding still produces a slow steady-state verdict");
        for (var i = 0; i < 10_000; i++) health.Observe(66, false, 1_000_000);
        check(health.Count <= GpuEncodeHealthWindow.MaximumSamples, "GPU health: repeated timestamps cannot grow retained samples without bound");
        health.Reset();
        check(health.Count == 0 && health.Observe(900, false, 99_000_000) is null,
            "GPU health: reopening an encoder resets its sample window and startup allowance");
        check(VideoStreamRun.SlowGpuCooldown == TimeSpan.FromMinutes(2), "GPU health: a slow-source verdict expires after two minutes for the next stream");
        using (var bytes = new MemoryStream())
        {
            var writer = new VideoRecordWriter(bytes, () => 1);
            uint? published = null; var beforeAnyBytes = false;
            var sequence = await writer.WriteAsync(VideoRecordType.Heartbeat, false, ReadOnlyMemory<byte>.Empty, CancellationToken.None,
                beforeWrite: value => { published = value; beforeAnyBytes = bytes.Length == 0; });
            check(beforeAnyBytes && published == 0 && sequence == published && bytes.Length == VideoStreamRecords.HeaderBytes,
                "Startup: receipt accounting receives the exact serialized sequence before the first byte leaves");
        }
        using (var bytes = new MemoryStream())
        {
            var writer = new VideoRecordWriter(bytes, () => 1, uint.MaxValue); var called = false;
            var sequence = await writer.WriteAsync(VideoRecordType.Heartbeat, false, ReadOnlyMemory<byte>.Empty, CancellationToken.None,
                beforeWrite: _ => called = true);
            check(sequence is null && !called && bytes.Length == 0,
                "Startup: exhausted sequence space never reserves a nonexistent access unit");
        }
        using (var bytes = new MemoryStream())
        {
            var writer = new VideoRecordWriter(bytes, () => 1); var threw = false;
            try
            {
                await writer.WriteAsync(VideoRecordType.Heartbeat, false, ReadOnlyMemory<byte>.Empty, CancellationToken.None,
                    beforeWrite: _ => throw new IOException("Synthetic accounting failure"));
            }
            catch (IOException) { threw = true; }
            check(threw && writer.IsBroken && bytes.Length == 0,
                "Startup: a failed accounting callback breaks the writer without exposing an untracked record");
        }
        var monitor = new MonitorInfo("synthetic-1", "Synthetic", -1920, 0, 64, 48, true);
        using var connection = new CancellationTokenSource();
        using var output = new ReceiptDuringFlushStream();
        await using var run = new VideoStreamRun(output, () => { }, new VideoStreamChecks.SyntheticSource(64, 48) { AutoAdvance = true }, monitor,
            (width, height, fps, bitrate) => new VideoStreamChecks.FakeEncoder(width, height, fps) { KeyframeBytes = 213_000 },
            new(240, 8_000_000, 1), () => VideoStreamDenial.None, connection.Token, CancellationToken.None,
            new(HeartbeatMilliseconds: 60_000));
        var futureAcksIgnored = true;
        output.Receipt = sequence =>
        {
            var before = (run.InFlight, run.InFlightBytes);
            run.Ack(sequence + 100, null);
            futureAcksIgnored &= before == (run.InFlight, run.InFlightBytes);
            // The peer has every byte while the server has not completed FlushAsync.
            run.Ack(sequence, null);
        };
        var running = Task.Run(run.RunAsync);
        try
        {
            var deadline = Environment.TickCount64 + 2000;
            while (output.Receipts < 3 && Environment.TickCount64 < deadline) await Task.Delay(5);
            check(output.Receipts >= 3,
                $"Startup: an ACK during Flush releases the oversized first keyframe (receipts={output.Receipts}, inFlightBytes={run.InFlightBytes})");
            check(futureAcksIgnored, "Startup: publishing the in-progress AU never accepts an unknown future ACK");
        }
        finally
        {
            await connection.CancelAsync();
            await running.WaitAsync(TimeSpan.FromSeconds(3));
        }
    }

    private sealed class ReceiptDuringFlushStream : Stream
    {
        private readonly object gate = new();
        private int remaining;
        private uint sequence;
        private bool accessUnit, receiptPending;
        private int receipts;
        public Action<uint>? Receipt { get; set; }
        public int Receipts => Volatile.Read(ref receipts);
        public override ValueTask WriteAsync(ReadOnlyMemory<byte> buffer, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            lock (gate)
            {
                if (remaining == 0)
                {
                    if (buffer.Length != VideoStreamRecords.HeaderBytes) throw new InvalidOperationException("Expected a record header.");
                    accessUnit = buffer.Span[0] == (byte)VideoRecordType.AccessUnit;
                    remaining = checked((int)BinaryPrimitives.ReadUInt32LittleEndian(buffer.Span[4..]));
                    sequence = BinaryPrimitives.ReadUInt32LittleEndian(buffer.Span[8..]);
                }
                else
                {
                    remaining -= buffer.Length;
                    if (remaining < 0) throw new InvalidOperationException("Record exceeded its header length.");
                    receiptPending = accessUnit && remaining == 0;
                }
            }
            return ValueTask.CompletedTask;
        }
        public override Task FlushAsync(CancellationToken cancellationToken)
        {
            cancellationToken.ThrowIfCancellationRequested();
            uint? received = null;
            lock (gate) if (receiptPending) { receiptPending = false; received = sequence; }
            if (received is { } value) { Receipt?.Invoke(value); Interlocked.Increment(ref receipts); }
            return Task.CompletedTask;
        }
        public override bool CanRead => false;
        public override bool CanSeek => false;
        public override bool CanWrite => true;
        public override long Length => throw new NotSupportedException();
        public override long Position { get => throw new NotSupportedException(); set => throw new NotSupportedException(); }
        public override void Flush() { }
        public override int Read(byte[] buffer, int offset, int count) => throw new NotSupportedException();
        public override long Seek(long offset, SeekOrigin origin) => throw new NotSupportedException();
        public override void SetLength(long value) => throw new NotSupportedException();
        public override void Write(byte[] buffer, int offset, int count) => throw new NotSupportedException();
    }
}
